// Auto-generated mock participant data sourced from RIYADH and JEDDAH 2025-26 registers
export interface MockParticipant {
  id: string;
  uniqueId: string;
  fullName: string;
  age: number;
  nationality: string;
  joinedDate: string;
  dob: string;
  status: 'Active' | 'WaitList' | 'Inquiry' | 'Documents Pending' | 'Fee Pending' | 'On Hold' | 'Completed' | 'Withdrawn';
  location: 'RIYADH' | 'JEDDAH';
  day: string;
  session: string;
  ageGroup: string;
  guardianName: string;
  guardianPhone: string;
  guardianEmail: string;
  withKit: boolean;
  documents: { name: string; status: 'Uploaded' | 'Missing' | 'Pending' }[];
  notes: { text: string; author: string; timestamp: string }[];
  registrationData?: {
    emergencyContactName?: string;
    emergencyContactPhone?: string;
    medicalConditions?: string;
    previousExperience?: string;
    source?: string;
    consentSigned?: boolean;
  };
}

